    14	// It's kind of a kludge, but one of these babies can pretend to be either 1-D or 2-D.
    15	// The 2-D variety can also be indexed using 1-D indexing.
    16	public final class FZZ32Vector extends fortress.CompilerBuiltin.ZZ32Vector.DefaultTraitMethods
    17	        implements fortress.CompilerBuiltin.ZZ32Vector {
    18	    private int[] val;
    19	    int lower_x, dim_x, lower_y, dim_y;
    20	
    21	    private FZZ32Vector(int[] a, int l1, int d1, int l2, int d2) {
    22		val = a; lower_x = l1; dim_x = d1; lower_y = l2; dim_y = d2;
    23	    }
    24	
    25	    public static FZZ32Vector make(int l1, int d1, int l2, int d2) {
    26	        return new FZZ32Vector(new int[(d2 == 0) ? d1 : d1 * d2], l1, d1, l2, d2);
    27	    }
    28	
    29	    public String toString() {
    30		StringBuffer result = new StringBuffer();
    31		if (dim_y == 0) {
    32		    // One-dimensional case
    33		    result.append("[");
    34		    for (int j = 0; j < dim_x; j++) {
    35			if (j > 0) result.append(" ");
    36			result.append(this.getIndexedValue(j));
    37		    }
    38		    result.append("]");
    39		} else {
    40		    // Two-dimensional case
    41		    result.append("\n(");
    42		    result.append(dim_x);
    43		    result.append(",");
    44		    result.append(dim_y);
    45		    result.append(")\n[");
    46		    for (int i = 0; i < dim_x; i++) {
    47			for (int j = 0; j < dim_y; j++) {
    48			    result.append(" ");
    49			    result.append(this.getIndexedValue(i,j));
    50			}
    51			if (i < dim_x-1) result.append("\n ");
    52			else result.append(" ]");
    53		    }
    54		}
    55		return result.toString();
    56	    }
    57	
    58	    public int dim()  {return val.length;}
    59	    public int rows() {return dim_x;}
    60	    public int cols() {return dim_y;}
    61	
    62	    public FJavaString asString() { return FJavaString.make(toString());}
    63	    
    64	    public int getIndexedValue(int i) {return val[i-lower_x];}
    65	    public int getIndexedValue(int i, int j) {return val[(i-lower_x)*dim_y + (j-lower_y)];}
    66	
    67	    public void putIndexedValue(int i, int newval) {val[i-lower_x] = newval;}
    68	    public void putIndexedValue(int i, int j, int newval) {val[(i-lower_x)*dim_y + (j-lower_y)] = newval;}
    69	
    70	    public int[] getValue() {return val;}
    71	
    72	    public static FZZ32Vector make(int[] v) {
    73	        return new FZZ32Vector(v, 0, v.length, 0, 0);
    74	    }
